const tabId = 248688717;

const projectCards = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll("section.projects ul > li, .projects-list > li, li.project, [itemprop='itemListElement']")).filter(el => {
    const link = el.querySelector("a[href*='/projects/']");
    return link && link.href.includes("/projects/");
  });

  return cards.map(c => {
    const title = c.querySelector("h2, h3, .project-title, [itemprop='name']")?.innerText?.trim();
    const url = c.querySelector("a[href*='/projects/']")?.href;
    const desc = c.querySelector(".description, .summary, [itemprop='description'], p")?.innerText?.trim();
    const text = c.innerText;

    // Find downloads specifically
    let downloads = "";
    const dlMatch = text.match(/Downloads:\s*([^\n\r]+)/i);
    if (dlMatch) downloads = dlMatch[1].trim();

    // Find rating / reviews
    let reviews = "";
    const revMatch = text.match(/(\d+\s+Reviews?)/i);
    if (revMatch) reviews = revMatch[1].trim();

    // Find last update
    let lastUpdate = "";
    const updateMatch = text.match(/Last Update:\s*([^\n\r]+)/i);
    if (updateMatch) lastUpdate = updateMatch[1].trim();

    return { title, url, downloads, reviews, lastUpdate, text: text.replace(/\s+/g, ' ') };
  });
});

