const projectDetails = await browserjs(tabId, () => {
  const title = document.querySelector("h1, .project-title")?.innerText?.trim();
  const categories = Array.from(document.querySelectorAll("section.categories a, .breadcrumbs a, a[href*='/directory/']")).map(a => a.innerText.trim());

  // Extract metadata / project info section
  const metadata = {};
  const metaSections = Array.from(document.querySelectorAll(".metadata-section, section, .project-info, .sidebar section, #project-categories, .tech-info"));

  // Look for dl / dt / dd or key-value pairs
  Array.from(document.querySelectorAll("dt, th, .label")).forEach(el => {
    const key = el.innerText.trim();
    const val = el.nextElementSibling?.innerText?.trim();
    if (key && val) metadata[key] = val;
  });

  // Also full text of sections
  const fullTech = document.querySelector(".tech-info, #project-tech-info, section.tech")?.innerText || document.body.innerText;

  return {
    title,
    categories: Array.from(new Set(categories)),
    metadata,
    techSnippets: fullTech.match(/(Operating System|License|Intended Audience|Programming Language|Development Status|Status|User Interface)[\s\S]{1,100}/gi)
  };
});

