const tabId = 248688717;

const prodMatch = await browserjs(tabId, () => {
  const matches = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const text = walker.currentNode.nodeValue;
    if (text.toLowerCase().includes("production") || text.toLowerCase().includes("stable")) {
      matches.push({
        text: text.trim(),
        parent: walker.currentNode.parentElement.tagName,
        parentClass: walker.currentNode.parentElement.className
      });
    }
  }
  return matches;
});

