const tabId = 248688717;

const pageDetails = await browserjs(tabId, () => {
  // Breadcrumbs
  const breadcrumbs = Array.from(document.querySelectorAll(".breadcrumbs a, .breadcrumbs span, .breadcrumbs li")).map(el => el.innerText?.trim());

  // Active filters
  const activeFilters = Array.from(document.querySelectorAll(".facet-selected, .filter-selected, .facet-applied, .selected-facet, [class*='selected'], [class*='applied']")).map(el => el.innerText?.trim());

  // All facet sections
  const facetSections = Array.from(document.querySelectorAll(".facet, .sidebar-section, .facet-wrapper")).map(sec => {
    const title = sec.querySelector("h3, h4, .facet-title, .title")?.innerText?.trim() || "Unknown";
    const items = Array.from(sec.querySelectorAll("li, a, .filter-choice")).map(item => ({
      text: item.innerText?.trim()?.replace(/\s+/g, " "),
      href: item.querySelector("a")?.href || (item.tagName === "A" ? item.href : null)
    })).filter(i => i.text);
    return { title, items: items.slice(0, 10) };
  });

  // Sort options
  const sortOptions = Array.from(document.querySelectorAll("#sort-by option, .sort-by option, select[name*='sort'] option")).map(opt => ({
    text: opt.innerText?.trim(),
    value: opt.value,
    selected: opt.selected
  }));

  // Results count & first few projects
  const resultCount = document.querySelector(".results-count, .count, .num-results")?.innerText?.trim();
  const projects = Array.from(document.querySelectorAll(".project_info, .project-card, .item, article")).map(p => ({
    title: p.querySelector(".title, h2, h3")?.innerText?.trim(),
    downloads: p.querySelector(".downloads, [class*='download']")?.innerText?.trim(),
    description: p.querySelector(".description, p")?.innerText?.trim()?.slice(0, 100)
  })).filter(p => p.title);

  return { breadcrumbs, activeFilters, facetSections, sortOptions, resultCount, projectsCount: projects.length, sampleProjects: projects.slice(0, 5) };
});

console.log("Page details:", JSON.stringify(pageDetails, null, 2));

