// Let's inspect the page
const pageStatus = await browserjs(tabId, () => {
  const title = document.title;
  const h1 = document.querySelector("h1")?.innerText;

  // Selected facets / active filters
  const selectedFilters = Array.from(document.querySelectorAll(".facet-selected, .filter-selected, [class*='selected'], .breadcrumb, .breadcrumbs")).map(e => e.innerText.trim().replace(/\s+/g, ' '));

  // Projects list
  // Look for project cards / search results
